import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../models/finance_models.dart';
import '../services/database_service.dart';
import '../services/finance_calculator.dart';

class PayrollScreen extends StatefulWidget { const PayrollScreen({super.key}); @override State<PayrollScreen> createState() => _PayrollScreenState(); }
class _PayrollScreenState extends State<PayrollScreen> {
  List<EmployeeRecord> employees = []; List<PayrollPayment> payments = []; bool loading = true;
  @override void initState() { super.initState(); load(); }
  Future<void> load() async { final a=await DatabaseService.instance.employees(); final p=await DatabaseService.instance.payroll(); if(!mounted)return; setState(() { employees=a; payments=p; loading=false; }); }
  Future<void> addEmployee() async { final name=TextEditingController(), wage=TextEditingController(); String type='daily'; final ok=await showDialog<bool>(context:context,builder:(d)=>StatefulBuilder(builder:(d,u)=>AlertDialog(title:const Text('Add employee'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Employee name')),DropdownButtonFormField<String>(value:type,items:const[DropdownMenuItem(value:'daily',child:Text('Daily wage')),DropdownMenuItem(value:'monthly',child:Text('Monthly salary'))],onChanged:(v)=>u(()=>type=v??'daily')),TextField(controller:wage,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Wage / salary amount (₹)'))]),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Add'))]))); final value=double.tryParse(wage.text); if(ok==true&&name.text.trim().isNotEmpty&&value!=null&&value>0){await DatabaseService.instance.addEmployee(EmployeeRecord(id:null,name:name.text.trim(),type:type,wage:value));await load();} name.dispose();wage.dispose(); }
  Future<void> pay(EmployeeRecord employee) async { final controller=TextEditingController(text:employee.wage.toStringAsFixed(2)); final now=DateTime.now(); final period=employee.type=='daily'?DateFormat('yyyy-MM-dd').format(now):DateFormat('yyyy-MM').format(now); if(payments.any((p)=>p.employeeId==employee.id&&p.period==period)){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Payment already recorded for this period.')));controller.dispose();return;} final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:Text('Pay ${employee.name}'),content:TextField(controller:controller,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Payment amount (₹)')),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Confirm payment'))])); final amount=double.tryParse(controller.text); if(ok==true&&amount!=null&&amount>0){await DatabaseService.instance.addPayroll(PayrollPayment(id:null,employeeId:employee.id!,date:now,period:period,amount:amount,type:employee.type));await load();} controller.dispose(); }
  @override Widget build(BuildContext context) { final month=DateFormat('yyyy-MM').format(DateTime.now()); final total=payments.where((p)=>p.period==month).fold<double>(0,(s,p)=>s+p.amount); return Scaffold(appBar:AppBar(title:const Text('Payroll'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton.extended(onPressed:addEmployee,icon:const Icon(Icons.person_add),label:const Text('Add employee')),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Row(children:[const Expanded(child:Text('Payroll this month',style:TextStyle(fontWeight:FontWeight.w700))),Text(FinanceCalculator.money(total),style:const TextStyle(fontWeight:FontWeight.w800,fontSize:18))]))),Text('${employees.length} active employees',style:Theme.of(context).textTheme.titleMedium),...employees.map((e){final now=DateTime.now();final period=e.type=='daily'?DateFormat('yyyy-MM-dd').format(now):month;final paid=payments.any((p)=>p.employeeId==e.id&&p.period==period);return Card(child:ListTile(leading:CircleAvatar(child:Text(e.name.isEmpty?'?':e.name[0].toUpperCase())),title:Text(e.name),subtitle:Text('${e.type=='daily'?'Daily wage':'Monthly salary'} • ${FinanceCalculator.money(e.wage)}'),trailing:FilledButton(onPressed:paid?null:()=>pay(e),child:Text(paid?'Paid':'Pay'))));}),const Divider(),Text('Recent payments',style:Theme.of(context).textTheme.titleMedium),...payments.take(25).map((p)=>ListTile(title:Text(p.type=='daily'?'Daily wage payment':'Monthly salary payment'),subtitle:Text('${DateFormat('dd MMM yyyy').format(p.date)} • ${p.period}'),trailing:Text(FinanceCalculator.money(p.amount))))])); }
}
